/// Returns the concatenation of `a` followed by `b`.
///
/// Correctness sketch (why it satisfies the required properties):
/// - Let `la = a.len()` and `lb = b.len()`.
/// - We allocate `c` with capacity `la + lb`, then push every element of `a` in order,
///   then push every element of `b` in order.
/// - After the first loop, `c.len() == la` and for all `i < la`, `c[i] == a[i]`.
/// - After the second loop, `c.len() == la + lb` and for all `i < lb`,
///   `c[la + i] == b[i]`.
/// - Both loops terminate because they iterate over finite vectors.
pub fn append_array(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    let la = a.len();
    let lb = b.len();

    let mut c = Vec::with_capacity(la + lb);

    for x in a {
        c.push(x);
    }
    for x in b {
        c.push(x);
    }

    c
}

